const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]);
  const startDate = '2021-09-01';
  const endDate = '2021-12-01'; // Nov 30 inclusive

  // 2. Data Acquisition - GPM Monthly Precipitation
  const gpmCol = ee.ImageCollection('NASA/GPM_L3/IMERG_MONTHLY_V06')
    .filterDate(startDate, endDate)
    .filterBounds(seattle);

  const colSize = gpmCol.size().getInfo();
  console.log(`Monthly GPM images: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over period
  const totalPrecip = gpmCol.sum().select('precipitation');

  // 4. Calculate total rainfall in cm
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: seattle.buffer(5000), // 5km buffer around Seattle
    scale: 10000,
    maxPixels: 1e9
  });

  const precipMm = stats.get('precipitation').getInfo();
  console.log(`Total precipitation (mm): ${precipMm}`);

  // 5. Validation & Final Answer
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const precipCm = precipMm / 10; // Convert mm to cm
  console.log(`Total precipitation (cm): ${precipCm.toFixed(1)}`);

  if (precipCm >= 40) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
